    );

    adder_8bit adder_upper (
        .a(a[15:8]),
        .b(b[15:8]),
        .Cin(Co1),
        .y(y2),
        .Co(Co)
    );

    assign y = {y2, y1};
endmodule

module adder_8bit(
    input [7:0] a,
    input [7:0] b,
    input Cin,
    output [7:0] y,
    output Co
);
    wire [8:0] sum;
    assign sum = a + b + Cin;
    assign y = sum[7:0];
    assign Co = sum[8];
endmodule

module adder_16bit(
    input [15:0] a,
    input [15:0] b,
    input Cin,
    output [15:0] y,
    output Co
);
    wire Co1;
    wire [7:0] y1, y2;

    adder_8bit adder_lower (
        .a(a[7:0]),
        .b(b[7:0]),
        .Cin(Cin),
        .y(y1),
        .Co(Co1)
    );

    adder_8bit adder_upper (
        .a(a[15:8]),
        .b(b[15:8]),
        .Cin(Co1),
        .y(y2),
        .Co(Co)
    );

    assign y = {y2, y1};
endmodule
